Here is the commit message:
selftests/bpf: Fix race in tcp_rtt test

Previous attempt to make tcp_rtt more robust introduced a new race, in which
server_done might be set to true before server can actually accept any
connection. Fix this by unconditionally waiting for accept(). Given socket is
non-blocking, if there are any problems with client side, it should eventually
close listening FD and let server thread exit with failure.

Fixes: 4cd729fa022c ("selftests/bpf: Make tcp_rtt test more robust to failures")
Signed-off-by: Andrii Nakryiko <andriin@fb.com>
Signed-off-by: Daniel Borkmann <daniel@iogearbox.net>
Acked-by: Martin KaFai Lau <kafai@fb.com>
Link: https://lore.kernel.org/bpf/20200314013932.4035712-1-andriin@fb.com

Here is the root cause:
The bug was caused by a race condition where the `server_done` flag could be set to true before the server thread had a chance to accept any incoming connections. This premature setting of the flag led to the server thread potentially exiting before it was ready, resulting in failures during the test execution.

Here is the patch:

 static void *server_thread(void *arg)
 {
 	struct sockaddr_storage addr;
 	socklen_t len = sizeof(addr);
 	int fd = *(int *)arg;
 	int client_fd;
 	int err;

 	err = listen(fd, 1);

 	pthread_mutex_lock(&server_started_mtx);
 	pthread_cond_signal(&server_started);
 	pthread_mutex_unlock(&server_started_mtx);

 	if (CHECK_FAIL(err < 0)) {
 		perror("Failed to listed on socket");
 		return ERR_PTR(err);
 	}

-	while (!server_done) {
+	while (true) {
 		client_fd = accept(fd, (struct sockaddr *)&addr, &len);
 		if (client_fd == -1 && errno == EAGAIN) {
 			usleep(50);
 			continue;
 		}
 		break;
 	}
 	if (CHECK_FAIL(client_fd < 0)) {
 		perror("Failed to accept client");
 		return ERR_PTR(err);
 	}

 	while (!server_done)
 		usleep(50);

 	close(client_fd);

 	return NULL;
 }

 void test_tcp_rtt(void)
 {
 	int server_fd, cgroup_fd;
 	pthread_t tid;
 	void *server_res;

 	cgroup_fd = test__join_cgroup("/tcp_rtt");
 	if (CHECK_FAIL(cgroup_fd < 0))
 		return;

 	server_fd = start_server();
 	if (CHECK_FAIL(server_fd < 0))
 		goto close_cgroup_fd;

 	if (CHECK_FAIL(pthread_create(&tid, NULL, server_thread,
 				      (void *)&server_fd)))
 		goto close_server_fd;

 	pthread_mutex_lock(&server_started_mtx);
 	pthread_cond_wait(&server_started, &server_started_mtx);
 	pthread_mutex_unlock(&server_started_mtx);

 	CHECK_FAIL(run_test(cgroup_fd, server_fd));

 	server_done = true;
-	pthread_join(tid, &server_res);
+	CHECK_FAIL(pthread_join(tid, &server_res));
 	CHECK_FAIL(IS_ERR(server_res));

 close_server_fd:
 	close(server_fd);
 close_cgroup_fd:
 	close(cgroup_fd);
 }
